    private final JdbcTemplate jdbc;
    public AgentRuntimeV2ExecutionMapper(JdbcTemplate jdbc){this.jdbc=Objects.requireNonNull(jdbc);}
    public JdbcTemplate jdbc(){return jdbc;}
    public Map<String,Object> select(String table,Map<String,Object> key,boolean lock){table(table);if(key.isEmpty())throw new IllegalArgumentException("empty key");if(lock)transaction();var args=new ArrayList<Object>();var rows=jdbc.query("SELECT "+projection(table)+" FROM "+table+" WHERE "+predicate(key,args)+(lock?" FOR UPDATE":""),rowMapper(table),args.toArray());if(rows.isEmpty())return null;if(rows.size()!=1)throw new SecurityException("ambiguous stable identity");var r=rows.getFirst();key.forEach((k,v)->{if(!same(r.get(k),v))throw new SecurityException("nonexact stable ID");});return r;}
    public List<Map<String,Object>> rows(String table,String dispatch,boolean lock){table(table);if(!Set.of(RECEIPT,FACT,ANCHOR,REQUEST,GRANT).contains(table))throw new IllegalArgumentException("not history");if(lock)transaction();return jdbc.query("SELECT "+projection(table)+" FROM "+table+" WHERE runtime_dispatch_id=? ORDER BY "+TABLES.get(table)+(lock?" FOR UPDATE":""),rowMapper(table),dispatch);}
    public void append(String table,Map<String,Object> values){transaction();if(!Set.of(RECEIPT,FACT,ANCHOR,REQUEST,GRANT).contains(table))throw new IllegalArgumentException("not append-only");values.keySet().forEach(AgentRuntimeV2ExecutionMapper::column);if(jdbc.update("INSERT INTO "+table+"("+String.join(",",values.keySet())+") VALUES("+String.join(",",Collections.nCopies(values.size(),"?"))+")",values.values().toArray())!=1)throw new IllegalStateException("append failed");}
    public void cas(String table,Map<String,Object> before,Map<String,Object> changes){transaction();if(!Set.of(INBOX,DELIVERY).contains(table))throw new IllegalArgumentException("not projection");var values=new LinkedHashMap<>(changes);values.put("version",Math.addExact(number(before,"version"),1));var key=row("id",before.get("id"),"version",before.get("version"));if(table.equals(INBOX))key.putAll(row("runtime_dispatch_id",before.get("runtime_dispatch_id"),"execution_origin_snapshot_sha256",before.get("execution_origin_snapshot_sha256"),"execution_current_lease_fact_id",before.get("execution_current_lease_fact_id"),"execution_lease_revision",before.get("execution_lease_revision")));else key.put("status",before.get("status"));var args=new ArrayList<Object>();var set=new ArrayList<String>();values.forEach((k,v)->{column(k);set.add(k+"=?");args.add(v);});if(jdbc.update("UPDATE "+table+" SET "+String.join(",",set)+" WHERE "+predicate(key,args),args.toArray())!=1)throw new IllegalStateException("execution projection CAS lost");}
    private static List<String> columns(String names){return List.of(names.split(","));}
    private static String projection(String table){return String.join(",",COLUMNS.get(table));}
    private static RowMapper<Map<String,Object>> rowMapper(String table){
        var columns=COLUMNS.get(table);
        return (resultSet,rowNumber)->{
            var result=new LinkedHashMap<String,Object>(columns.size());
            for(int index=0;index<columns.size();index++)result.put(columns.get(index),JdbcUtils.getResultSetValue(resultSet,index+1));
            return result;
        };
    }
    private static String predicate(Map<String,Object> key,List<Object> args){var terms=new ArrayList<String>();key.forEach((k,v)->{column(k);terms.add(k+(v==null?" IS NULL":"=?"));if(v!=null)args.add(v);});return String.join(" AND ",terms);}
    private static void column(String c){if(!COLUMN_NAME.matcher(c).matches())throw new IllegalArgumentException("column");}
    private static void table(String t){if(!TABLES.containsKey(t))throw new IllegalArgumentException("table");}
    private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive()||TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!TransactionSynchronizationManager.hasResource(jdbc.getDataSource()))throw new IllegalStateException("bound write transaction required");}
